"""Recovery contracts and an explicitly simulated developer point of view."""
import json
from build_final_project_workshop import icon


def build_recovery(root,twin,p,table):
    data=json.loads((root/'final-project/recovery.json').read_text())
    def duration(seconds):
        return '0' if not seconds else str(seconds//3600)+' h' if seconds%3600==0 else str(seconds//60)+' min' if seconds%60==0 else str(seconds)+' s'
    rows=[]
    details=''
    for row in data['cases']:
        rows.append([(row['id']+' · '+row['name'][0],row['id']+' · '+row['name'][1]),('<bdi dir="ltr">'+duration(row['rpo_seconds'])+'</bdi>','<bdi dir="ltr">'+duration(row['rpo_seconds'])+'</bdi>'),('<bdi dir="ltr">'+duration(row['rto_seconds'])+'</bdi>','<bdi dir="ltr">'+duration(row['rto_seconds'])+'</bdi>'),tuple(row['scope'])])
        details+=f'<details class="recovery-case" id="{row["id"]}"><summary><bdi>{row["id"]}</bdi>'+twin(*row['name'])+icon('plus')+'</summary><div class="disclosure-body">'
        for key,fa,en in [('why','چرا این هدف را انتخاب کردیم؟','Why choose this target?'),('budget','بودجهٔ بازیابی','Recovery budget'),('requires','چه چیزی باید برقرار باشد؟','Required conditions'),('test','چطور آن را اثبات کنیم؟','How to demonstrate it')]:
            details+='<h4>'+twin(fa,en)+'</h4>'+p(*row[key])
        details+='</div></details>'
    return '<section id="recovery" class="workshop-section recovery-section"><h2 class="workshop-heading"><span class="secnum" aria-hidden="true">05</span>'+twin('اگر سیستم خراب شد، چه قولی می‌دهیم؟','What happens when the system fails?')+'</h2>'+p('RPO می‌گه حداکثر چقدر از آخرین داده‌ها رو می‌تونیم از دست بدیم. RTO می‌گه حداکثر چقدر وقت داریم تا سرویسِ درست برگرده. این‌ها دو قرارداد جدا‌ان و برای هر نوع خرابی جدا انتخاب می‌شن.','RPO tells you how much of the latest data you can afford to lose. RTO tells you how long you have to get the correct service back. They\'re two separate contracts, and each failure type gets its own.')+'<div class="recovery-definitions"><div><h3 lang="en" dir="ltr">RPO · Recovery Point Objective</h3>'+p('مثال: RPO پنج دقیقه یعنی نقطهٔ بازیابیِ پیوسته حداکثر پنج دقیقه عقب باشه؛ backup روزانه به‌تنهایی کافی نیست.','Example: a five-minute RPO means the contiguous recovery point is never more than five minutes behind. A daily backup alone won\'t cut it.')+'</div><div><h3 lang="en" dir="ltr">RTO · Recovery Time Objective</h3>'+p('ساعت از آغاز اختلال شروع می‌شه، نه از وقتی تیم اعلامش کرد. و پایانش وقتیه که canary سرتاسری با داده و مجوز درست قبول بشه — نه صرفاً وقتی DB روشن شد.','The clock starts when the outage starts, not when the team says so. And it ends when an end-to-end canary passes with the right data and permissions — not when the DB merely boots.')+'</div></div><p class="recovery-status">'+twin('هدف‌های منتخبِ طراحی پایلوت — هنوز نه اندازه‌گیری شدن و نه پیاده‌سازی. این جدول، SLA میزبانی سایت نیست.','Selected pilot design objectives — still neither measured nor implemented. This table is not the study site\'s hosting SLA.')+'</p>'+table([('سناریو','Scenario'),('سقف RPO','RPO limit'),('سقف RTO','RTO limit'),('مرزِ ادعا','Scope')],rows)+details+'<div class="recovery-measure"><h3>'+twin('ثبت نتیجهٔ drill، قبل از هر ادعای پایداری','Record the drill before claiming resilience')+'</h3>'+p('قبل از خرابی، یه canary شماره‌دار رو در journal مستقل ثبت می‌کنیم. بعد آخرین نقطهٔ پیوستهٔ قابل‌بازیابی، دادهٔ ازدست‌رفته و زمان بازگشتِ canary رو مقایسه می‌کنیم. snapshot و WAL باید با artifactها، guard حذف و policy فعلی سازگار باشن.','Before the failure, we write a numbered canary into an independent journal. Then we compare the last contiguous recovery point, the data we lost, and the time until a canary came back. The snapshot and WAL have to agree with the artifacts, the deletion guards, and the current policy.')+p('توی restore، ACL قدیمی مجوزِ فعلی نیست. اگه IAM معتبر، حذف‌ها یا fencing قابل‌اثبات نباشن، دسترسی حساس بسته می‌مونه و RTO ناموفق ثبت می‌شه. «replica داریم» یا «archive_timeout رو تنظیم کردیم» به‌تنهایی مدرکِ این هدف‌ها نیست.','A restored ACL is not current authority. If IAM, the deletions, or the fencing can\'t be validated, sensitive access stays shut and the RTO goes down as a miss. “We have replicas” or “we set archive_timeout” is not proof of any of this.')+'</div>'+p('برای خودِ وب‌سایتِ فعلی: RPO نسبت به آخرین commit تأییدشده در GitHub صفره؛ تغییرهای محلیِ push‌نشده بیرون این ادعا می‌مونن. هدفِ redeploy دستی ۳۰ دقیقه‌ست و هنوز drill نشده؛ تضمینِ Vercel یا GitHub نیست.','For this very website: the RPO is zero relative to the last verified GitHub commit; unpushed local changes sit outside that claim. The manual-redeploy objective is 30 minutes, and nobody has drilled it yet — it isn\'t a Vercel or GitHub guarantee.')+'<div class="workshop-links"><a class="workshop-link" href="#ADR-015">ADR-015'+icon('next')+'</a><a class="workshop-link" href="recovery.json">'+twin('قراردادها و فرض‌ها (JSON)','Contracts and assumptions (JSON)')+icon('next')+'</a><a class="workshop-link" href="../docs/RECOVERY.md">'+twin('راهنمای آزمون بازیابی','Recovery drill guide')+icon('next')+'</a></div><p class="recovery-sources"><a href="https://docs.aws.amazon.com/whitepapers/latest/disaster-recovery-workloads-on-aws/introduction.html" target="_blank" rel="noopener">AWS · RPO/RTO</a> · <a href="https://www.postgresql.org/docs/current/continuous-archiving.html" target="_blank" rel="noopener">PostgreSQL · PITR</a> · <a href="https://www.postgresql.org/docs/current/runtime-config-wal.html" target="_blank" rel="noopener">PostgreSQL · WAL</a></p></section>'


def build_outcome(twin,p,ul):
    scenes=[
        ('تعریف برنامه','Define the app','برنامه و ابزارهای مجازش رو تعریف می‌کنم.','I define the app and the tools it\'s allowed to use.','Configured',
         '<dl class="pov-config"><div><dt>App</dt><dd>Incident Investigator</dd></div><div><dt>Tenant</dt><dd>demo-sandbox</dd></div><div><dt>Model</dt><dd>Provider adapter · proposed</dd></div><div><dt>Tools</dt><dd>read_metrics · read_traces · read_runbook</dd></div></dl>'),
        ('درخواست اجرا','Submit a run','یه alert می‌فرستم؛ همون کلیدِ درخواست باید همیشه همون run رو برگردونه.','I submit an alert; the same request key has to return the same run every time.','Accepted',
         '<dl class="pov-config"><div><dt>Run ID</dt><dd>run_demo_001</dd></div><div><dt>Idempotency</dt><dd>alert_demo_001</dd></div><div><dt>State</dt><dd>Committed before acknowledgement</dd></div></dl>'),
        ('جمع‌آوری شاهد','Gather evidence','فقط منابعِ مجازِ همین tenant خونده می‌شن. این سه مقدار، دادهٔ مصنوعیِ سناریو هستن.','Only this tenant\'s permitted sources get read. These three values are synthetic scenario data.','Running',
         '<dl class="pov-config"><div><dt>Metrics</dt><dd>Connection pool: 98% used</dd></div><div><dt>Traces</dt><dd>Database connection wait increased</dd></div><div><dt>Deployment</dt><dd>v42 · before the alert</dd></div></dl>'),
        ('قطع worker','Worker interrupted','worker از دسترس می‌ره؛ ولی اطلاعاتِ commit‌شدهٔ run هنوز توی مخزن پایداره.','The worker drops off; the run\'s committed state is still sitting in durable storage.','Interrupted',
         '<div class="pov-incident">'+p('توی نمایش، اجرای worker شمارهٔ ۷ قطع می‌شه. سرویس واقعی رو kill نمی‌کنیم.','In the demo, worker number 7 gets interrupted. We don\'t kill any real service.')+'</div><dl class="pov-config"><div><dt>Committed step</dt><dd>2 · retained</dd></div><div><dt>Run ID</dt><dd>run_demo_001 · unchanged</dd></div></dl>'),
        ('ادامهٔ همان run','Resume the same run','مالک تازه با epoch جدید ادامه می‌ده؛ و commit مالک قدیمی باید رد بشه. هدف R01: دادهٔ تأییدشده گم نشه و بازیابی تا دو دقیقه.','A fresh owner takes over with a new epoch, and the old owner\'s commit has to be rejected. R01 wants two things: no acknowledged data lost, and recovery inside two minutes.','Resuming',
         '<dl class="pov-config"><div><dt>Owner epoch</dt><dd>7 → 8</dd></div><div><dt>Resume</dt><dd>After committed step 2</dd></div><div><dt>R01 objective</dt><dd>RPO = 0 · RTO ≤ 120 s · not measured</dd></div></dl>'),
        ('خواندن گزارش','Inspect the report','گزارش رو همراهِ شاهد و عدم‌قطعیتش می‌خونم؛ ابزارِ دارای اثر در این نسخه اجرا نمی‌شه.','I read the report with its evidence and its uncertainty attached. This version runs no side-effecting tool.','Report ready',
         '<div class="pov-report"><h4>'+twin('فرضیهٔ اول: اشباع connection pool','Leading hypothesis: connection-pool exhaustion')+'</h4>'+ul([('شاهد: استفادهٔ ۹۸٪ از pool و انتظارِ بیشترِ DB در trace.','Evidence: 98% pool usage and longer DB waits in the traces.'),('ابهام: هم‌زمانی با deployment علت رو ثابت نمی‌کنه.','Uncertainty: landing on top of the deployment doesn\'t prove it caused anything.'),('گام بعدِ پیشنهادی: یه مهندس leak و تنظیم pool رو چک کنه.','Suggested next step: an engineer goes looking for leaks and pool configuration.')])+'</div>'),
        ('آزمونِ نسخه','Evaluate the release','قبل از ارتقای نسخه، آزمونِ کیفیت و خرابی لازمه. این نمایش فقط مسیر کار رو توضیح می‌ده؛ eval واقعی اجرا نشده.','Quality and failure tests come before a promotion. This walkthrough only shows the path — no real evaluation runs here.','Review required',
         '<div class="pov-report"><h4>'+twin('مدرکی که برای انتشار می‌خواهیم','Evidence required before release')+'</h4>'+ul([('نتیجهٔ holdout و مقایسه با baseline','Holdout results compared against the baseline'),('drillهای RPO/RTO با زمان و دادهٔ مشاهده‌شده','RPO/RTO drills with the times and data we actually observed'),('کنترل ACL، حذف و worker قدیمی','ACL, deletion, and stale-worker checks')])+'<a class="workshop-link" href="#acceptance">'+twin('دیدن آزمون‌های برنامه‌ریزی‌شده','View planned acceptance tests')+icon('next')+'</a></div>'),
    ]
    navigation='<div class="pov-step-nav" hidden aria-label="Developer walkthrough">'
    articles=''
    options=''
    for i,(fa,en,nfa,nen,state,content) in enumerate(scenes):
        options+=f'<option value="{i}" data-fa="{i+1:02} · {fa}" data-en="{i+1:02} · {en}">{i+1:02} · {fa}</option>'
        navigation+=f'<button type="button" data-pov-select="{i}" aria-pressed="{str(i==0).lower()}"><bdi>{i+1:02}</bdi>'+twin(fa,en)+'</button>'
        articles+=f'<article data-pov-scene="{i}"><div class="pov-screen-heading"><h3>'+twin(fa,en)+f'</h3><span class="pov-state" dir="ltr">{state}</span></div>'+p(nfa,nen)+content+'</article>'
    navigation+='</div><label class="pov-mobile-nav" hidden>'+twin('انتخاب گام','Choose a step')+'<select id="pov-stage-select">'+options+'</select></label>'
    summary='<div class="outcome-summary"><div><h3>'+twin('آنچه الان ساخته‌ایم','What exists today')+'</h3>'+ul([('یه سایت آموزشی دو‌زبانه با ۱۴ فصل، به‌علاوهٔ یه کارگاه طراحی پلتفرم.','A bilingual 14-chapter study site, plus a platform-design workshop.'),('۱۵ ADR، تخمین‌های قابل‌تغییر، قراردادهای بازیابی، و نمودارهای معماری/UML.','15 ADRs, editable estimates, recovery contracts, and architecture/UML diagrams.'),('یه فلو و walkthrough نمایشی — و محاسبات و کنترل‌هاش واقعاً توی مرورگرِ تو کار می‌کنن.','An illustrative flow and walkthrough — and their calculations and controls really do run in your browser.')])+'</div><div><h3>'+twin('پلتفرمی که این طرح توصیف می‌کند','The platform described by the design')+'</h3>'+p('توسعه‌دهنده app رو تعریف می‌کنه، run می‌فرسته و نتیجه و trace می‌گیره؛ هستهٔ مشترک، context مجاز، اجرای پایدار، gateway و ارزیابی نسخه رو فراهم می‌کنه. API، worker، DB، CDC و serving این پلتفرم هنوز پیاده‌سازی نشدن.','A developer defines an app, submits runs, and picks up results and traces. The shared core supplies authorized context, durable execution, a gateway, and release evaluation. Its APIs, workers, database, CDC, and model serving are still not implemented.')+'</div></div>'
    player='<div class="pov-player" id="pov-player"><div class="pov-topline"><strong lang="en" dir="ltr">Own the Stack / Developer workspace</strong><span>'+twin('نمایش آموزشی با دادهٔ مصنوعی','Educational simulation · synthetic data')+'</span></div><div class="pov-layout">'+navigation+'<div class="pov-screen">'+articles+'</div></div><div class="pov-toolbar" hidden><button type="button" data-pov-play class="langbtn" aria-pressed="false">'+icon('play')+'<span data-pov-play-label>'+twin('پخش تجربه','Play walkthrough')+'</span></button><span data-pov-counter></span><div class="flow-manual"><button type="button" data-pov-prev class="quiet-button">'+icon('next')+twin('قبل','Previous')+'</button><button type="button" data-pov-next class="quiet-button">'+twin('بعد','Next')+icon('next')+'</button><button type="button" data-pov-reset class="quiet-button">'+icon('reset')+twin('از ابتدا','Restart')+'</button></div></div></div>'
    return '<section id="outcome" class="workshop-section outcome-section"><h2>'+twin('در پایان، چه چیزی داریم؟','What have we made?')+'</h2>'+summary+'<h3 class="pov-title">'+twin('از دید توسعه‌دهنده، یک بار مسیر را ببینیم','See the journey from the developer’s point of view')+'</h3>'+p('این POV یه پیش‌نمایش تعاملی از محصولِ پیشنهادیه؛ هیچ مدل، ابزار، DB یا سرویس خارجی رو صدا نمی‌زنه. و زمان پخش هم RTO اندازه‌گیری‌شده نیست.','This POV is an interactive preview of the proposed product. It calls no model, tool, database, or external service — and the playback time is not a measured RTO.')+player+'<noscript>'+p('با JavaScript خاموش، همهٔ گام‌ها به‌صورت متن قابل‌خواندن‌ان.','With JavaScript off, every step is still readable as plain text.')+'</noscript><div class="project-signature"><p>'+twin('طراحی، نگارش و نگهداری این پروژه:','Project design, writing, and maintenance:')+'</p><strong lang="en" dir="ltr">hurdad ashouri</strong><div class="workshop-links"><a href="https://github.com/Hurdadd/own-the-stack" class="workshop-link">GitHub'+icon('next')+'</a><a href="../README.md" class="workshop-link">README'+icon('next')+'</a><a href="../CONTRIBUTING.md" class="workshop-link">'+twin('مشارکت','Contributing')+icon('next')+'</a><a href="../LICENSE" class="workshop-link">AGPL-3.0-only'+icon('next')+'</a></div><p class="signature-note">'+twin('مجوز برای کارِ اصیل پروژه‌ست؛ حقِ کتاب، فونت‌ها و اجزای ثالث طبق NOTICE و مجوز خودشون محفوظه. وب‌سایت و مخزن GitHub عمومیه.','The license covers the project\'s original work; the book, the fonts, and the third-party parts stay under NOTICE and their own licenses. The website and the GitHub repository are public.')+'</p></div></section>'
